const express = require('express');
const { getCoverageStore } = require('../testing/coverageStore');
const { verifyStagingToken } = require('../auth');

const app = express();

app.get('/staging/jest/reporters/coverage/:runId', verifyStagingToken, async (req, res) => {
  const { runId } = req.params;

  const coverageStore = getCoverageStore();
  const report = await coverageStore.getCoverage(runId);

  if (!report) {
    return res.status(404).json({ error: 'Coverage report not found' });
  }

  // Verify that the caller's team or organization has authorization to view this project run
  if (report.orgId !== req.user.orgId && !req.user.allowedProjects?.includes(report.projectName)) {
    return res.status(403).json({ error: 'Access denied: You are not authorized to view coverage for this project' });
  }

  res.json({
    runId: report.id,
    project: report.projectName,
    sourceMap: report.sourceCoverage,
    environmentSummary: report.envSummary
  });
});

module.exports = app;
